let cases = List.map Json.parse encoded_cases
let arguments raw =
  let input = field "input" raw in
  Realization_request.of_json (field "request" input),
  Synthetic_authority.Candidate.of_json (field "candidate" input),
  (Json.array (field "history" input) |> List.map Execution_data.Input_frame.of_json),
  (match field "until" input with Json.Null -> None | value -> Some (Runtime_number.of_json value))
let run ?limits ?parent raw =
  let request,candidate,history,until = arguments raw in
  A.adapt ?until ?limits ?parent request candidate history
let equal message expected actual = require (Canonical.encode expected = Canonical.encode actual) message
let () =
  require (List.length cases = 33 && Canonical.sha256 (String.concat "\n" encoded_cases) = "ad0e5e94a4bb8214303509ba8b0e6cb39898c04ba7b1c5aff2572cea70421d06")
    "Complete original adapter literal census or bytes changed";
  List.iter (fun raw ->
    let id = text "id" raw in
    match text "outcome" raw with
    | "returned" ->
        let produced = run raw in
        equal (id ^ ": full registry/composition/acceptance changed") (field "result" raw) (A.to_json produced);
        let request,candidate,history,until = arguments raw in
        let assembly = Component_assembly.make ~registry:(A.registry produced) ~composition:(A.composition produced)
            ~request_fingerprint:(Realization_request.fingerprint request)
            ~candidate_fingerprint:(Synthetic_authority.Candidate.fingerprint candidate)
            ~behavior_sources:(Synthetic_authority.Candidate.source_map candidate)
            ~observation_map:(Synthetic_authority.Candidate.observation_map candidate) in
        require (Composition_evidence.Result.passed (K.check ?until request candidate assembly history))
          (id ^ ": producer output failed independent full source/assembly checking")
    | "raised" ->
        (match run raw with
         | _ -> failwith (id ^ ": original rejection was accepted")
         | exception Diagnostic.Error error ->
             require (error.code = text "native_expected_code" raw && error.message = text "message" (field "error" raw))
               (id ^ ": original exact acceptance prerequisite changed"))
    | _ -> failwith "Unknown adapter literal outcome") cases;
  let case name = List.find (fun raw -> text "id" raw = "independent_adapter:" ^ name) cases in
  let alias = case "custom_boolean_domain_alias" in
  let alias_request,alias_candidate,alias_history,alias_until = arguments alias in
  equal "Boolean alias stopped passing the independent synthetic prerequisite"
    (field "synthetic_acceptance" alias)
    (Bioc_realization_checker.Synthetic_candidate_check.check ?until:alias_until
      alias_request alias_candidate alias_history |> Realization_evidence.Check_result.to_json);
  let baseline = case "baseline" in
  let request,candidate,history,until = arguments baseline in
  let produced,usage = A.adapt_with_usage ?until request candidate history in
  let raw = A.to_json produced in
  require (usage.work_charged > 0 && usage.request_bytes > 0 && usage.report_bytes > 0 && usage.retained_peak > 0)
    "Adapter omitted preparation, publication or retained-state accounting";
  let exact,charged = A.adapt_with_usage ?until ~limits:(A.make_limits ~max_work:usage.work_charged ()) request candidate history in
  equal "Exact complete local work boundary failed" raw (A.to_json exact);
  require (charged.work_charged = usage.work_charged) "Work accounting changed with an exact allowance";
  rejected "realization_work_limit" (fun () -> A.adapt ?until
    ~limits:(A.make_limits ~max_work:(usage.work_charged-1) ()) request candidate history);
  let parent = W.create ~profile:"adapter.literal" ~error_code:"adapter_parent" ~maximum:usage.work_charged () in
  equal "Exact parent work boundary failed" raw (A.to_json (A.adapt ?until ~parent request candidate history));
  require (W.remaining parent = 0) "Fresh acceptance or production escaped shared parent work";
  let short = W.create ~profile:"adapter.literal" ~error_code:"adapter_parent" ~maximum:(usage.work_charged-1) () in
  rejected "adapter_parent" (fun () -> A.adapt ?until ~parent:short request candidate history);
  List.iter (fun (code,limits) -> rejected code (fun () -> A.adapt ?until ~limits request candidate history))
    ["realization_work_limit",A.make_limits ~max_work:1 ();
     "realization_input_limit",A.make_limits ~max_request_bytes:1 ();
     "realization_report_limit",A.make_limits ~max_report_bytes:1 ();
     "realization_report_limit",A.make_limits ~max_report_nodes:1 ();
     "realization_monitor_limit",A.make_limits ~max_monitor_items:1 ()];
  equal "Exact input boundary failed" raw (A.to_json (A.adapt ?until
    ~limits:(A.make_limits ~max_request_bytes:usage.request_bytes ()) request candidate history));
  rejected "realization_input_limit" (fun () -> A.adapt ?until
    ~limits:(A.make_limits ~max_request_bytes:(usage.request_bytes-1) ()) request candidate history);
  equal "Exact cumulative publication boundary failed" raw (A.to_json (A.adapt ?until
    ~limits:(A.make_limits ~max_report_bytes:usage.report_bytes ()) request candidate history));
  rejected "realization_report_limit" (fun () -> A.adapt ?until
    ~limits:(A.make_limits ~max_report_bytes:(usage.report_bytes-1) ()) request candidate history);
  let actual = case "in_band_actual_candidate" in
  require (field "candidate" (field "input" actual) <> field "candidate" (field "input" baseline))
    "Literal in-band witness failed to change the actual candidate";
  equal "Changed accepted witness was replaced with default generation" (field "result" actual) (A.to_json (run actual));
  let rejected_case = List.find (fun raw -> text "outcome" raw = "raised") cases in
  let failure_parent = W.create ~profile:"adapter.literal.failure" ~error_code:"adapter_failure_parent" ~maximum:50_000_000 () in
  rejected "synthetic_component_acceptance" (fun () -> run ~parent:failure_parent rejected_case);
  let remaining = W.remaining failure_parent in
  rejected "synthetic_component_acceptance" (fun () -> run ~parent:failure_parent rejected_case);
  require (W.remaining failure_parent < remaining && remaining < 50_000_000)
    "Failed prerequisites reused a saved acceptance or fresh allowance";
  let first = List.hd history in
  let rec cyclic_history = first :: cyclic_history in
  rejected "realization_input_limit" (fun () -> A.adapt ?until request candidate cyclic_history);
  equal "Failure contaminated independent retry" raw (A.to_json (A.adapt ?until request candidate history));
  print_endline "synthetic adaptation: 30 full original/independent productions, 2 exact prerequisite failures, 1 exact compatible Boolean alias rejection, fresh independent assembly checks, altered actual witness, shared bounds and failure isolation"
